    List<String> allPinnedPackages(){String saved=pref().getString("favorites",null);ArrayList<String> items=new ArrayList<>();if(saved==null){for(int i=0;i<Math.min(3,apps.size());i++)items.add(apps.get(i).pkg);}else for(String pkg:saved.split(","))for(NativeApp app:apps)if(app.pkg.equals(pkg)&&!items.contains(pkg)&&items.size()<7)items.add(pkg);return items;}
